const ACTIVITY_ICON={proposal_created:`film`,proposal_commented:`chat`,proposal_chosen:`ticket`,group_joined:`join`,film_rated:`star`,watchlist_added:`bookmark`,list_created:`list`};function rowToActivityEvent(row){return{id:row.id,scope:row.scope,actorId:row.actor_id,groupId:row.group_id,eventType:row.event_type,targetLabel:row.target_label,targetPosterUrl:row.target_poster_url,targetNote:row.target_note,createdAt:row.created_at}}async function loadActivity({scope,groupId=null,eventType=null,limit=20}={}){let query=supabaseClient.from(`activity_events`).select(`*`).eq(`scope`,scope).order(`created_at`,{ascending:false}).limit(limit);if(groupId!=null)query=query.eq(`group_id`,groupId);if(eventType!=null)query=query.eq(`event_type`,eventType);const{data,error}=await query;if(error){console.error(error);return[]}const events=(data||[]).map(rowToActivityEvent);const missing=[...new Set(events.map(e=>e.actorId))].filter(id=>!friendProfiles[id]);if(missing.length){const{data:profs,error:profErr}=await supabaseClient.from(`profiles`).select(`user_id, display_name, avatar_url`).in(`user_id`,missing);if(profErr)console.error(profErr);else profs.forEach(p=>cacheProfile(p.user_id,p.display_name,p.avatar_url))}return events}function activityEventLabel(e){const name=friendDisplayName(e.actorId);switch(e.eventType){case`proposal_created`:return`${name} a proposé « ${e.targetLabel} »`;case`proposal_commented`:return`${name} a commenté « ${e.targetLabel} »`;case`proposal_chosen`:return`${name} a élu « ${e.targetLabel} » comme prochaine séance`;case`group_joined`:return`${name} a rejoint le groupe`;case`film_rated`:return`${name} a noté « ${e.targetLabel} »${e.targetNote!=null?` ${e.targetNote}/5`:``}`;case`watchlist_added`:return`${name} a ajouté « ${e.targetLabel} » à sa liste À voir`;case`list_created`:return`${name} a créé la liste « ${e.targetLabel} »`;default:return name}}function renderActivityRowHtml(e){return`
    <div class="wl-row">
      ${friendAvatarHtml(e.actorId,friendDisplayName(e.actorId))}
      <div class="wl-main">
        <div class="wl-title">${ACTIVITY_ICON[e.eventType]?uiIcon(ACTIVITY_ICON[e.eventType]):``} ${escapeHtml(activityEventLabel(e))}</div>
        <div class="wl-note">${formatViewingDate(e.createdAt)}</div>
      </div>
    </div>
  `}function renderActivityListInto(el,events){renderCollapsible(el,events,renderActivityRowHtml,{previewCount:4,emptyHtml:`<div class="tmdb-empty">Rien à signaler pour l'instant.</div>`})}